{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Version Graph Identity Representation Witness",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "cases"
  ],
  "properties": {
    "version": {
      "const": 1
    },
    "cases": {
      "type": "array",
      "minItems": 12,
      "items": {
        "oneOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "entity"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "payload"
                ],
                "properties": {
                  "payload": {
                    "type": "array",
                    "items": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 255
                    }
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "scoped"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "editId",
                  "ordinal"
                ],
                "properties": {
                  "editId": {
                    "type": "string"
                  },
                  "ordinal": {
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 4294967295
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "edit"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "replica",
                  "sequence",
                  "fingerprint"
                ],
                "properties": {
                  "replica": {
                    "type": "string",
                    "pattern": "^[0-9]+$"
                  },
                  "sequence": {
                    "type": "integer",
                    "minimum": -2147483648,
                    "maximum": 2147483647
                  },
                  "fingerprint": {
                    "type": "array",
                    "items": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 255
                    }
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "change"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "editIds",
                  "description"
                ],
                "properties": {
                  "editIds": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  },
                  "description": {
                    "type": [
                      "string",
                      "null"
                    ]
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "alternative"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "name",
                  "checkpointIds"
                ],
                "properties": {
                  "name": {
                    "type": "string"
                  },
                  "checkpointIds": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          },
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "prefix",
              "input",
              "preimageHex"
            ],
            "properties": {
              "kind": {
                "const": "mutation"
              },
              "prefix": {
                "type": "string",
                "minLength": 1
              },
              "input": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "operation",
                  "stamp"
                ],
                "properties": {
                  "operation": {
                    "type": "array",
                    "items": {
                      "type": "integer",
                      "minimum": 0,
                      "maximum": 255
                    }
                  },
                  "stamp": {
                    "type": "array",
                    "minItems": 3,
                    "maxItems": 3,
                    "items": {
                      "type": "string",
                      "pattern": "^[0-9]+$"
                    }
                  }
                }
              },
              "preimageHex": {
                "type": "string",
                "pattern": "^(?:[0-9a-f]{2})*$"
              }
            }
          }
        ]
      }
    }
  }
}

